    async def screenshot(
        self,
        browser_id: str,
        page_id: str,
        *,
        space_id: typing.Optional[ScreenshotPagesRequestSpaceId] = None,
        idempotency_key: typing.Optional[str] = None,
        format: typing.Optional[BrowsersPagesScreenshotRequestFormat] = OMIT,
        full_page: typing.Optional[bool] = OMIT,
        quality: typing.Optional[int] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> PageScreenshotResult:
        """
        Capture one page of the current Browser Run as PNG or JPEG, optionally the full page. The image is returned base64 encoded. Interrupted execution returns unknown with null data.

        Parameters
        ----------
        browser_id : str

        page_id : str
            Unique page identifier generated by BCTRL.

        space_id : typing.Optional[ScreenshotPagesRequestSpaceId]

        idempotency_key : typing.Optional[str]
            Optional retry key for this billable operation. Reusing the same key with the same request replays its stable outcome; credential-bearing results may be freshly issued for the same principal. Reusing it with a different request returns 409.

        format : typing.Optional[BrowsersPagesScreenshotRequestFormat]

        full_page : typing.Optional[bool]

        quality : typing.Optional[int]

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        PageScreenshotResult
            OK

        Examples
        --------
        import asyncio

        from bctrl import AsyncBctrl

        client = AsyncBctrl(
            bctrl_space="YOUR_BCTRL_SPACE",
            bctrl_subaccount_id="YOUR_BCTRL_SUBACCOUNT_ID",
            token="YOUR_TOKEN",
        )


        async def main() -> None:
            await client.browsers.pages.screenshot(
                browser_id="browserId",
                page_id="pageId",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.screenshot(
            browser_id,
            page_id,
            space_id=space_id,
            idempotency_key=idempotency_key,
            format=format,
            full_page=full_page,
            quality=quality,
            request_options=request_options,
        )
        return _response.data
